mapper.select:
SELECT s.id, s.doctor_id, s.schedule_date, s.time_slot, s.total_quota, s.booked_count, s.status, s.create_time, s.update_time, doc.name AS doctor_name, doc.title AS title, dep.name AS department_name, (SELECT COUNT(*) FROM appointment a WHERE a.schedule_id = s.id) AS appointment_count FROM schedule s LEFT JOIN doctor doc ON doc.id = s.doctor_id LEFT JOIN department dep ON dep.id = doc.department_id
AND s.doctor_id = #{doctorId}
AND s.schedule_date >= #{startDate}
AND s.schedule_date <= #{endDate}
ORDER BY s.schedule_date ASC, s.time_slot ASC, s.id ASC

SELECT COUNT(*) FROM appointment
WHERE schedule_id = #{scheduleId}
  AND status NOT IN ('cancelled', 'completed')
